corrected_code:
const express = require('express');
const { Subscription, PaymentMethod } = require('../models');
const { authenticateToken } = require('../auth');

const app = express();

Subscription.addHook('afterFind', async (results) => {
  if (!results) return;
  const items = Array.isArray(results) ? results : [results];
  for (const item of items) {
    if (item.paymentMethodId) {
      item.setDataValue('paymentMethod', await PaymentMethod.findByPk(item.paymentMethodId));
    }
  }
});

app.get('/api/billing/subscriptions/:id', authenticateToken, async (req, res) => {
  // Restrict query to the authenticated user's subscriptions
  const subscription = await Subscription.findOne({
    where: {
      id: req.params.id,
      userId: req.user.id
    }
  });

  if (!subscription) {
    return res.status(404).json({ error: 'Subscription not found or access denied' });
  }

  res.json({ subscription });
});

app.listen(8106);
